void test_validation_ssrf_allowlisted_loopback(void) {
    /* SSRF allowlist permits a loopback mock server while private-network protection remains enabled */
    CBERGAlefHandle config_handle = cberg_crawl_config_from_json("{\"respect_robots_txt\":false,\"ssrf\":{\"allowlist\":[{\"type\":\"cidr\",\"value\":\"127.0.0.0/8\"}],\"deny_private\":true,\"max_redirects\":5},\"ssrf_deny_private_explicit\":true}");
    assert(config_handle != 0 && "failed to parse config");
    CBERGAlefHandle engine = cberg_create_engine(config_handle);
    cberg_crawl_config_free(config_handle);
    assert(engine != 0 && "failed to create engine");
    const char* mock_per_fixture = getenv("MOCK_SERVER_VALIDATION_SSRF_ALLOWLISTED_LOOPBACK");
    const char* mock_base = getenv("MOCK_SERVER_URL");
    char url[2048];
    if (mock_per_fixture && mock_per_fixture[0] != '\0') {
        snprintf(url, sizeof(url), "%s", mock_per_fixture);
    } else {
        assert(mock_base != NULL && "MOCK_SERVER_URL must be set");
        snprintf(url, sizeof(url), "%s/fixtures/validation_ssrf_allowlisted_loopback", mock_base);
    }
    CBERGAlefHandle result = cberg_scrape(engine, url);
    assert(result != 0 && "expected call to succeed");
    uint16_t status_code = cberg_scrape_result_status_code(result);
    CBERGAlefHandle metadata_handle = cberg_scrape_result_metadata(result);
    assert(metadata_handle != 0);
    char* metadata_title = cberg_page_metadata_title(metadata_handle);
    assert(status_code == 200 && "equals assertion failed");
    assert(metadata_title != NULL && strcmp(metadata_title, "Allowlisted") == 0 && "equals assertion failed");
    cberg_free_string(metadata_title);
    cberg_page_metadata_free(metadata_handle);
    cberg_scrape_result_free(result);
    cberg_crawl_engine_handle_free(engine);
}

